import ts from "typescript";
import path from "node:path";
import { listSourceFiles, rel } from "../acquisition/program.js";

/**
 * Source files whose content determines the *behavior* of the oracles below.
 * `gt.ts` hashes these to stamp each `gt-*.json` with the oracle version that
 * produced it (see `oracleVersionHash` in gt.ts), so a benchmark run can
 * refuse to score against ground truth generated by a since-patched oracle
 * instead of silently producing numbers like the pre-`all-fixes.patch`
 * FindCallees dip (constructor callees scored as false positives because the
 * bundled gt predated the oracle's `new X()` handling).
 */
export const ORACLE_SOURCE_FILES = [path.resolve(path.dirname(new URL(import.meta.url).pathname), "oracles-ext.ts")];

/**
 * Independent ground truth for FindCallees and ChangeImpact.
 *
 * These oracles are written against the raw TypeScript compiler API and share
 * no code with the engine's analyses, so an engine bug cannot hide inside the
 * oracle it is scored against.
 */

/**
 * `gt.ts` calls into these oracles once per task (~5 task types x N symbols
 * per repo), and on a large repo like zod, `ts.createProgram` alone — parsing
 * and binding every file — dominates the runtime if repeated per call. Every
 * oracle call for a given repo root operates on the same unchanged source
 * (this process never mutates the checked-out corpus), so a `ts.Program` is
 * safe to reuse across calls within one `gt.ts` invocation. Callers that
 * genuinely need a fresh, uncached program (e.g. isolation tests) can bypass
 * the cache with `createProgram(root, { fresh: true })`.
 */
const programCache = new Map<string, ts.Program>();

export function createProgram(root: string, opts: { fresh?: boolean } = {}): ts.Program {
  const key = path.resolve(root);
  if (!opts.fresh && programCache.has(key)) return programCache.get(key)!;
  const files = listSourceFiles(root);
  const program = ts.createProgram(files, {
    allowJs: true,
    target: ts.ScriptTarget.ES2022,
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    skipLibCheck: true,
    strict: false,
  });
  if (!opts.fresh) programCache.set(key, program);
  return program;
}

function declarationsNamed(program: ts.Program, root: string, name: string): { node: ts.Node; file: string }[] {
  const out: { node: ts.Node; file: string }[] = [];
  for (const sf of program.getSourceFiles()) {
    if (sf.isDeclarationFile) continue;
    if (!path.resolve(sf.fileName).startsWith(path.resolve(root))) continue;
    const visit = (node: ts.Node) => {
      if ((ts.isFunctionDeclaration(node) || ts.isMethodDeclaration(node)) && node.name && node.name.getText(sf) === name) {
        out.push({ node, file: sf.fileName });
      }
      ts.forEachChild(node, visit);
    };
    ts.forEachChild(sf, visit);
  }
  return out;
}

/**
 * The identifier written at a call site can be a local import alias
 * (`export { FastRunner as QuickRunner } ...` then `new QuickRunner()`); the
 * engine's type-directed resolution reports the real declaration name
 * ("FastRunner"), so the oracle must resolve through the alias chain too, or
 * every aliased call site is scored as a name mismatch instead of a match.
 */
function resolvedDeclaredName(checker: ts.TypeChecker, sym: ts.Symbol | undefined, fallback: string): string {
  if (!sym) return fallback;
  let s = sym;
  while (s.flags & ts.SymbolFlags.Alias) {
    try {
      s = checker.getAliasedSymbol(s);
    } catch {
      break;
    }
  }
  const decl = s.declarations?.[0];
  if (decl && (ts.isClassDeclaration(decl) || ts.isFunctionDeclaration(decl) || ts.isMethodDeclaration(decl)) && decl.name) {
    return decl.name.getText();
  }
  return fallback;
}

/** Callee oracle: names of in-repo functions reachable in one hop from the body. */
export function calleeOracle(root: string, symbol: string): string[] {
  const program = createProgram(root);
  const checker = program.getTypeChecker();
  const out = new Set<string>();
  for (const decl of declarationsNamed(program, root, symbol)) {
    const body = (decl.node as ts.FunctionLikeDeclaration).body;
    if (!body) continue;
    const visit = (node: ts.Node) => {
      if (ts.isCallExpression(node)) {
        let callee: ts.Expression = node.expression;
        while (ts.isNonNullExpression(callee) || ts.isParenthesizedExpression(callee)) callee = callee.expression;
        let name: string | null = null;
        if (ts.isIdentifier(callee)) name = callee.text;
        else if (ts.isPropertyAccessExpression(callee)) name = callee.name.text;
        if (name) {
          // keep only callees that have an in-repo declaration
          const sym = checker.getSymbolAtLocation(callee);
          const target = sym?.declarations?.[0]?.getSourceFile();
          const inRepo = target ? path.resolve(target.fileName).startsWith(path.resolve(root)) : false;
          const declaredSomewhereInRepo = declarationsNamed(program, root, name).length > 0;
          if (inRepo || declaredSomewhereInRepo) out.add(resolvedDeclaredName(checker, sym, name));
        }
      } else if (ts.isNewExpression(node)) {
        // `new X()` executes X's constructor just as surely as a call does;
        // excluding NewExpression here (the original scope of this oracle)
        // silently under-counted every constructor-invoking callee, which
        // then scored the engine's (correct) constructor-callee findings as
        // false positives.
        let callee: ts.Expression = node.expression;
        while (ts.isNonNullExpression(callee) || ts.isParenthesizedExpression(callee)) callee = callee.expression;
        if (ts.isIdentifier(callee)) {
          const name = callee.text;
          const sym = checker.getSymbolAtLocation(callee);
          const target = sym?.declarations?.[0]?.getSourceFile();
          const inRepo = target ? path.resolve(target.fileName).startsWith(path.resolve(root)) : false;
          if (inRepo) out.add(resolvedDeclaredName(checker, sym, name));
        }
      }
      ts.forEachChild(node, visit);
    };
    ts.forEachChild(body, visit);
  }
  return [...out].sort();
}

/**
 * Reverse import graph: which repo files import which, resolved through the
 * compiler's own module resolution (not regex), including re-export
 * (`export ... from`) edges so barrel files propagate reachability.
 * Shared by importImpactOracle and testImpactOracle.
 */
function reverseImportGraph(program: ts.Program, root: string): Map<string, Set<string>> {
  const importers = new Map<string, Set<string>>();
  for (const sf of program.getSourceFiles()) {
    if (sf.isDeclarationFile) continue;
    if (!path.resolve(sf.fileName).startsWith(path.resolve(root))) continue;
    const from = rel(root, sf.fileName);
    for (const stmt of sf.statements) {
      const spec =
        (ts.isImportDeclaration(stmt) || ts.isExportDeclaration(stmt)) && stmt.moduleSpecifier
          ? (stmt.moduleSpecifier as ts.StringLiteral).text
          : null;
      if (!spec || !spec.startsWith(".")) continue;
      let resolved: ts.ResolvedModuleFull | undefined;
      try {
        resolved = ts.resolveModuleName(spec, sf.fileName, program.getCompilerOptions(), ts.sys).resolvedModule;
      } catch {
        resolved = undefined;
      }
      if (!resolved || !resolved.resolvedFileName) continue;
      const to = rel(root, resolved.resolvedFileName);
      if (to.startsWith("..")) continue;
      if (!importers.has(to)) importers.set(to, new Set());
      importers.get(to)!.add(from);
    }
  }
  return importers;
}

function bfsReachable(seedFile: string, importers: Map<string, Set<string>>): Set<string> {
  const seen = new Set<string>([seedFile]);
  const queue = [seedFile];
  while (queue.length) {
    const cur = queue.shift()!;
    for (const imp of importers.get(cur) ?? []) {
      if (!seen.has(imp)) {
        seen.add(imp);
        queue.push(imp);
      }
    }
  }
  return seen;
}

/**
 * ImportImpact oracle: files transitively importing the declaring file
 * (directly or through re-export/barrel chains). This is a *dependency*
 * notion of impact — "what could observe a change to this module's
 * exports" — independent of whether any code on the path actually calls
 * the changed symbol.
 */
export function importImpactOracle(root: string, symbol: string): string[] {
  const program = createProgram(root);
  const decls = declarationsNamed(program, root, symbol);
  if (decls.length === 0) return [];
  const origin = rel(root, decls[0]!.file);
  const importers = reverseImportGraph(program, root);
  return [...bfsReachable(origin, importers)].sort();
}

/**
 * Deprecated alias. `impactOracle` was the pre-split name for what is now
 * `importImpactOracle`; kept so any external caller that hasn't migrated
 * doesn't silently break. New code should call `importImpactOracle`,
 * `callImpactOracle`, or `testImpactOracle` directly.
 */
export const impactOracle = importImpactOracle;

/**
 * CallImpact oracle: declarations reachable by walking the reverse *call*
 * graph — i.e. "what could actually execute differently" — rather than the
 * reverse import graph. Unlike the engine's `impactOfChange` (bounded to
 * `maxDepth`, default 4), this walk is unbounded, so it is a fair target for
 * scoring the engine's call-graph traversal on its own terms: a precision
 * gap here is a real correctness bug, a recall gap here is a real coverage
 * bug, neither confounded by depth-bounding or import-vs-call conflation.
 *
 * A declaration is reachable if some call site inside it calls (or
 * constructs) something already known to reach the target — same
 * one-hop-per-declaration matching `calleeOracle` uses, run to closure.
 */
/**
 * Returns the function-like body of any node this oracle treats as a
 * "declaration" — function/method/constructor declarations directly, and
 * `const x = (...) => ...` / `const x = function() {...}` / class-field
 * arrow properties indirectly, by unwrapping to the initializer.
 *
 * The narrower version of this oracle (matching only `FunctionDeclaration`
 * and `MethodDeclaration`) silently could not see: (a) arrow-function or
 * function-expression consts — the dominant declaration style in some
 * codebases (e.g. ky's `const createInstance = (...) => {...}`), (b) class
 * constructors, which are a distinct AST node kind from `MethodDeclaration`,
 * not a special case of it, and (c) class-field arrow properties
 * (`foo = () => {...}`). Any real caller written in one of these forms was
 * invisible to the fixed-point closure below, which understated true
 * call-reachability and scored the engine's (correct) findings through
 * those callers as false positives.
 */
function functionLikeBody(node: ts.Node): ts.ConciseBody | undefined {
  if (ts.isFunctionDeclaration(node) || ts.isMethodDeclaration(node) || ts.isConstructorDeclaration(node)) {
    return node.body;
  }
  if (ts.isVariableDeclaration(node) && node.initializer) {
    let init = node.initializer;
    while (ts.isParenthesizedExpression(init)) init = init.expression;
    if (ts.isArrowFunction(init) || ts.isFunctionExpression(init)) return init.body;
  }
  if (ts.isPropertyDeclaration(node) && node.initializer) {
    let init = node.initializer;
    while (ts.isParenthesizedExpression(init)) init = init.expression;
    if (ts.isArrowFunction(init) || ts.isFunctionExpression(init)) return init.body;
  }
  return undefined;
}

/**
 * Declared name for any of the node kinds `functionLikeBody` recognizes.
 * A constructor is keyed by its *enclosing class's* name, not the literal
 * text "constructor" — `new ClassName()` call sites already resolve to
 * "ClassName" (via `resolvedDeclaredName`'s class-declaration case), so
 * keying the constructor itself the same way is what lets "who reaches
 * this class" link the two together. Keying by literal "constructor"
 * instead would silently merge every unrelated class's constructor into
 * one bucket: one class's constructor calling the target would make *all*
 * classes' constructors "reached", inflating the reachable file set with
 * every class in the repo regardless of whether its constructor actually
 * calls anything relevant.
 */
function functionLikeName(node: ts.Node, sf: ts.SourceFile): string | null {
  if (ts.isFunctionDeclaration(node) && node.name) return node.name.getText(sf);
  if (ts.isMethodDeclaration(node) && ts.isIdentifier(node.name)) return node.name.getText(sf);
  if (ts.isConstructorDeclaration(node)) {
    let p: ts.Node | undefined = node.parent;
    while (p && !ts.isClassDeclaration(p) && !ts.isClassExpression(p)) p = p.parent;
    if (p && (ts.isClassDeclaration(p) || ts.isClassExpression(p)) && p.name) return p.name.getText(sf);
    return null; // anonymous class constructor: no name a call site could reference
  }
  if (ts.isVariableDeclaration(node) && ts.isIdentifier(node.name)) return node.name.getText(sf);
  if (ts.isPropertyDeclaration(node) && ts.isIdentifier(node.name)) return node.name.getText(sf);
  return null;
}

export function callImpactOracle(root: string, symbol: string): string[] {
  const program = createProgram(root);
  const checker = program.getTypeChecker();

  // index every named function-like declaration in the repo (see
  // `functionLikeBody`/`functionLikeName` for exactly which node kinds
  // count), and the file each lives in, so we can do reverse lookup ("who
  // calls X") by name.
  const allDecls = new Map<string, { node: ts.Node; file: string }[]>();
  // Call/construct expressions written directly at a module's top level
  // (not inside any function-like body) are not "declarations" — they are
  // side effects that run unconditionally at import time. zod's entire
  // schema hierarchy is built this way (`export const ZodType =
  // core.$constructor("ZodType", ...)` at module scope), so without
  // tracking these separately, a whole class of real dependents was
  // invisible to the closure below no matter how much `allDecls` was
  // widened. Keyed by absolute file path.
  const moduleLevelCallees = new Map<string, Set<string>>();

  for (const sf of program.getSourceFiles()) {
    if (sf.isDeclarationFile) continue;
    if (!path.resolve(sf.fileName).startsWith(path.resolve(root))) continue;
    const calleeNamesIn = (node: ts.Node, out: Set<string>) => {
      if (ts.isCallExpression(node) || ts.isNewExpression(node)) {
        let callee: ts.Expression = node.expression;
        while (ts.isNonNullExpression(callee) || ts.isParenthesizedExpression(callee)) callee = callee.expression;
        if (ts.isIdentifier(callee)) out.add(resolvedDeclaredName(checker, checker.getSymbolAtLocation(callee), callee.text));
        else if (ts.isPropertyAccessExpression(callee)) out.add(callee.name.text);
      }
    };
    const moduleCallees = new Set<string>();
    const visit = (node: ts.Node, insideFunction: boolean) => {
      const name = functionLikeName(node, sf);
      const body = functionLikeBody(node);
      if (name && body) {
        if (!allDecls.has(name)) allDecls.set(name, []);
        allDecls.get(name)!.push({ node, file: sf.fileName });
        // walk this declaration's own body separately below (via allDecls),
        // so don't also fold its internal calls into module-level scope —
        // but still recurse into it to find nested declarations.
        ts.forEachChild(node, (child) => visit(child, true));
        return;
      }
      if (ts.isClassDeclaration(node) && node.name) {
        if (!allDecls.has(node.name.getText(sf))) allDecls.set(node.name.getText(sf), []);
      }
      if (!insideFunction) calleeNamesIn(node, moduleCallees);
      ts.forEachChild(node, (child) => visit(child, insideFunction));
    };
    ts.forEachChild(sf, (child) => visit(child, false));
    if (moduleCallees.size > 0) moduleLevelCallees.set(sf.fileName, moduleCallees);
  }

  const decls = allDecls.get(symbol) ?? [];
  if (decls.length === 0) return [];

  // for every declaration, the set of names it calls/constructs in its body
  // (one hop) — reused from calleeOracle's own extraction logic so the two
  // oracles can't silently disagree about what counts as a call. Computed
  // once per declaration up front (not inside the fixed-point loop below),
  // since the loop can otherwise re-walk every body on every iteration —
  // O(iterations x declarations x body size) instead of O(declarations x
  // body size), which is the difference between seconds and minutes on a
  // repo the size of zod.
  const calleesOf = (n: ts.Node): Set<string> => {
    const body = functionLikeBody(n);
    const out = new Set<string>();
    if (!body) return out;
    const visit = (node: ts.Node) => {
      if (ts.isCallExpression(node) || ts.isNewExpression(node)) {
        let callee: ts.Expression = node.expression;
        while (ts.isNonNullExpression(callee) || ts.isParenthesizedExpression(callee)) callee = callee.expression;
        if (ts.isIdentifier(callee)) out.add(resolvedDeclaredName(checker, checker.getSymbolAtLocation(callee), callee.text));
        else if (ts.isPropertyAccessExpression(callee)) out.add(callee.name.text);
      }
      ts.forEachChild(node, visit);
    };
    ts.forEachChild(body, visit);
    return out;
  };
  const calleesByName = new Map<string, Set<string>[]>();
  for (const [name, entries] of allDecls) {
    calleesByName.set(
      name,
      entries.map(({ node }) => calleesOf(node)),
    );
  }

  const targetName = symbol;
  const reachedNames = new Set<string>([targetName]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const [name, calleeSets] of calleesByName) {
      if (reachedNames.has(name)) continue;
      if (calleeSets.some((callees) => [...callees].some((c) => reachedNames.has(c)))) {
        reachedNames.add(name);
        changed = true;
      }
    }
  }
  reachedNames.delete(targetName);

  const files = new Set<string>();
  for (const { file } of decls) files.add(rel(root, file));
  // ORACLE FIX (Phase 1.2, repo-b) — declaration-site coverage gap.
  // `allDecls` only indexes function-like nodes that HAVE a body (see
  // `functionLikeBody`), because the fixed-point closure needs a body to
  // walk. But the *declaration sites* of the target symbol are impacted by
  // definition, body or not: an interface `MethodSignature`, an `abstract`
  // method, and an overload signature all declare the very symbol being
  // changed. Excluding them made the oracle omit e.g. repo-b's
  // `src/types.ts` (`interface Handler { handle(...) }` +
  // `abstract handle(...)`) from the impacted set, so the engine — which
  // correctly resolves `handle` to all five declarations — was charged a
  // false positive for that file (precision 0.80 on `handle`, the sole
  // cause of repo-b's CallImpact mean F1 0.9815). This widens only the
  // *declaration-site seed*; the closure logic is untouched, so no
  // caller-side judgement is relaxed.
  for (const sf of program.getSourceFiles()) {
    if (sf.isDeclarationFile) continue;
    if (!path.resolve(sf.fileName).startsWith(path.resolve(root))) continue;
    const visit = (node: ts.Node) => {
      const declaresTarget =
        (ts.isFunctionDeclaration(node) || ts.isMethodDeclaration(node) || ts.isMethodSignature(node)) &&
        node.name !== undefined &&
        ts.isIdentifier(node.name) &&
        node.name.text === symbol;
      if (declaresTarget) files.add(rel(root, sf.fileName));
      ts.forEachChild(node, visit);
    };
    ts.forEachChild(sf, visit);
  }

  for (const name of reachedNames) {
    for (const { file } of allDecls.get(name) ?? []) files.add(rel(root, file));
  }
  // Module-level call sites: a file whose top-level code calls something
  // already known to reach the target is itself impacted, even though
  // "the module's top level" isn't a named declaration that can appear in
  // `reachedNames` (there's no function to call *it*). This is what makes
  // zod's `export const ZodType = core.$constructor(...)` pattern visible.
  for (const [file, callees] of moduleLevelCallees) {
    if ([...callees].some((c) => c === targetName || reachedNames.has(c))) {
      files.add(rel(root, file));
    }
  }
  return [...files].sort();
}

/**
 * TestImpact oracle: test files (per the same `isTestFile` convention the
 * engine's `whichTestsExercise` uses) that could observe a change to the
 * target — reachable either by call-graph path or by import path, since a
 * test can exercise a symbol it never lexically calls (re-exported default,
 * a factory that constructs it, a barrel import) as easily as one it calls
 * directly. Union of both, not just call reachability, so this stays a
 * strictly *more inclusive* notion than CallImpact rather than a subset of
 * it — the two are allowed to disagree on which tests count.
 */
export function testImpactOracle(root: string, symbol: string): string[] {
  const program = createProgram(root);
  const decls = declarationsNamed(program, root, symbol);
  if (decls.length === 0) return [];
  const origin = rel(root, decls[0]!.file);
  const importers = reverseImportGraph(program, root);
  const viaImport = bfsReachable(origin, importers);
  const viaCall = new Set(callImpactOracle(root, symbol));
  viaCall.add(origin);
  const merged = new Set<string>([...viaImport, ...viaCall]);
  return [...merged].filter((f) => /(^|\/)tests?\//.test(f) || /\.(test|spec)\.[cm]?[jt]sx?$/.test(f)).sort();
}
